"""Generator discovery and exact-copy boundaries (fixtures generated by pinned CLIs)."""

import json
from pathlib import Path

import pytest

from skillsaw.blocks import ContentBlock, ExtraBlock, FrontmatterField
from skillsaw.blocks.generators import (
    RulerConfigBlock,
    RulerRuleBlock,
    RulesyncConfigBlock,
    RulesyncRuleBlock,
)
from skillsaw.config import LinterConfig
from skillsaw.context import RepositoryContext, RepositoryType
from skillsaw.formats.generators import parse_rulesync_frontmatter
from skillsaw.rules.builtin.generators.ruler_config_valid import RulerConfigValidRule
from skillsaw.rules.builtin.generators.rulesync_source_valid import RulesyncSourceValidRule
from tests.test_integration import copy_fixture


def context_for(name, tmp_path, **kwargs):
    repo = copy_fixture(f"generators/{name}", tmp_path)
    return repo, RepositoryContext(repo, **kwargs)


def copies(context):
    return {
        str(n.path.relative_to(context.root_path)): n.generated_copy
        for n in context.lint_tree.walk()
        if n.generated_copy
    }


@pytest.mark.parametrize(
    "name,kind,block_cls,config_cls,count",
    [
        ("ruler", RepositoryType.RULER, RulerRuleBlock, RulerConfigBlock, 2),
        ("rulesync", RepositoryType.RULESYNC, RulesyncRuleBlock, RulesyncConfigBlock, 3),
    ],
)
def test_sources_have_native_roles(name, kind, block_cls, config_cls, count, tmp_path):
    repo, context = context_for(
        name, tmp_path, content_paths=["**/*.md", "**/*.toml", "**/*.jsonc"]
    )
    assert kind in context.repo_types
    # The mixed Rulesync fixture also has Claude's native .claude layout.
    assert context.repo_type == (RepositoryType.DOT_CLAUDE if name == "rulesync" else kind)
    sources = context.lint_tree.find(block_cls)
    assert len(sources) == count
    assert all(s.category == "instruction" for s in sources)
    assert any("backend/api.md" in str(s.path) for s in sources)
    config = context.lint_tree.find(config_cls)
    assert len(config) == 1
    assert not isinstance(config[0], ContentBlock)
    assert not config[0].content_blocks()
    paths = {s.path for s in sources} | {config[0].path}
    assert all(n.path not in paths for n in context.lint_tree.find(ExtraBlock))


def test_ruler_plain_markdown_keeps_apparent_frontmatter(tmp_path):
    repo, context = context_for("ruler", tmp_path)
    path = repo / ".ruler/backend/api.md"
    path.write_text("---\ndescription: Read this as instruction prose\n---\n\n# API\n")
    block = next(n for n in context.lint_tree.find(RulerRuleBlock) if n.path == path)
    assert block.read_body(strip_code_blocks=False).startswith("---\ndescription:")
    assert not block.find(FrontmatterField)


def test_sources_without_generated_artifacts(tmp_path):
    repo, _ = context_for("rulesync", tmp_path)
    import shutil

    shutil.rmtree(repo / ".cursor")
    shutil.rmtree(repo / ".claude")
    (repo / "CLAUDE.md").unlink()
    context = RepositoryContext(repo)
    assert context.repo_types == {RepositoryType.RULESYNC}
    assert context.repo_type == RepositoryType.RULESYNC
    assert len(context.lint_tree.find(RulesyncRuleBlock)) == 3


@pytest.mark.parametrize("change", ["globs", "targets", "cursor", "claudecode", "merge"])
def test_native_normalization_preserves_copies(change, tmp_path):
    repo, _ = context_for("rulesync", tmp_path)
    path = repo / ".rulesync/rules/backend/api.md"
    content = path.read_text()
    if change == "globs":
        content = content.replace('globs: ["src/**/*.ts"]', 'globs: [null, "src/**/*.ts"]')
    elif change == "targets":
        content = content.replace(
            "targets: [claudecode, cursor]", "targets: [null, claudecode, cursor]"
        )
    elif change == "cursor":
        content = content.replace("cursor:\n", 'cursor:\n  globs: [null, "src/**/*.ts"]\n')
    elif change == "claudecode":
        content = content.replace(
            "root: false\n", 'root: false\nclaudecode:\n  paths: [null, "src/**/*.ts"]\n'
        )
    else:
        content = content.replace(
            "root: false\n",
            "defaults: &defaults\n  <<: {root: true}\n  root: false\n<<: *defaults\n",
        )
    path.write_text(content)
    context = RepositoryContext(repo, rulesync_generated=True)
    assert not RulesyncSourceValidRule().check(context)
    assert {".cursor/rules/backend/api.mdc", ".claude/rules/backend/api.md"} <= set(copies(context))


def test_nested_source_roots_and_reserved_subtrees(tmp_path):
    repo, _ = context_for("ruler", tmp_path)
    for name in ("skills/tool/SKILL.md", "agents/reviewer.md", ".internal/notes.md"):
        path = repo / ".ruler" / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("# Notes\n\nUse the transaction boundary.\n")
    nested = repo / "packages/api/.rulesync/rules/backend/api.md"
    nested.parent.mkdir(parents=True)
    nested.write_text("---\nroot: false\n---\n\n# API\n")
    context = RepositoryContext(repo)
    ruler = {str(n.path.relative_to(repo)) for n in context.lint_tree.find(RulerRuleBlock)}
    assert ".ruler/.internal/notes.md" in ruler
    assert not any("/skills/" in p or "/agents/" in p for p in ruler)
    assert [n.path for n in context.lint_tree.find(RulesyncRuleBlock)] == [nested]


@pytest.mark.parametrize(
    "name,rule,kind",
    [
        ("ruler", RulerConfigValidRule, RepositoryType.RULER),
        ("rulesync", RulesyncSourceValidRule, RepositoryType.RULESYNC),
    ],
)
def test_valid_released_fixture_and_opt_in(name, rule, kind, tmp_path):
    repo, context = context_for(name, tmp_path)
    assert not rule().check(context)
    assert LinterConfig.default().rules[rule().rule_id]["enabled"] is False
    forced = RepositoryContext(repo, repo_types={RepositoryType.AGENTSKILLS})
    assert kind in forced.repo_types


@pytest.mark.parametrize(
    "header,valid",
    [
        ("", True),
        ("root: true\nglobs: [src/**]\n", True),
        ("root: yes\n", False),
        ("root: 1\n", False),
        ("description: no\n", True),
        ("description: 1e3\n", False),
        ("description: 2.5e4\n", False),
        ('description: "1e3"\n', True),
        ("metadata: {true: foo, 1: bar}\n", True),
        ('metadata: {true: foo, "true": bar}\n', False),
        ("description:\nroot:\n", True),
        ("cursor:\n  alwaysApply:\n", True),
        ("globs: [null]\n", True),
        ("globs: src/**\n", False),
        ("targets: [future-host]\n", True),  # The target registry stays with Rulesync.
        ("root: true\nroot: false\n", False),
        ("cursor: wrong\n", False),
    ],
)
def test_rulesync_frontmatter_contract(header, valid, tmp_path):
    repo, _ = context_for("rulesync", tmp_path)
    path = repo / ".rulesync/rules/extra.md"
    path.write_text(f"---\n{header}---\n\n# Example\n")
    violations = RulesyncSourceValidRule().check(RepositoryContext(repo))
    assert bool(violations) is not valid
    if violations:
        assert all(v.file_path == path and v.line is not None for v in violations)


@pytest.mark.parametrize(
    "key,canonical",
    [
        ("1e-7", "1e-7"),
        ("1e-6", "0.000001"),
        ("1e21", "1e+21"),
        ("1.0e20", "100000000000000000000"),
        ("1000000000000000128", "1000000000000000100"),
        ("9007199254740993", "9007199254740992"),
        ("-0.0", "0"),
        (".nan", "NaN"),
        (".inf", "Infinity"),
        ("-.inf", "-Infinity"),
        ("1e400", "Infinity"),
    ],
)
def test_rulesync_numeric_property_keys_match_released_parser(key, canonical):
    # Pinned gray-matter/js-yaml uses JavaScript Number and property-key spelling.
    parsed = parse_rulesync_frontmatter(f"---\n{key}: first\n---\n# Release\n")
    assert parsed[0] == {canonical: "first"}
    duplicate = parse_rulesync_frontmatter(
        f"---\n{key}: first\n{json.dumps(canonical)}: second\n---\n# Release\n"
    )
    assert duplicate[1:3] == ("Invalid YAML frontmatter", 3)


def test_rulesync_jsonc_config_and_severity(tmp_path):
    repo, _ = context_for("rulesync", tmp_path)
    config = repo / "rulesync.jsonc"
    config.write_text('{ // comment\n "targets": [], "global": "false", }')
    violations = RulesyncSourceValidRule({"severity": "warning"}).check(RepositoryContext(repo))
    assert len(violations) == 1
    assert violations[0].file_path == config
    assert violations[0].line is None
    assert violations[0].severity.value == "warning"


def test_ruler_bad_toml_shape_consolidated_without_values(tmp_path):
    repo, _ = context_for("ruler", tmp_path)
    config = repo / ".ruler/ruler.toml"
    config.write_text('nested = "SECRET-VALUE"\ndefault_agents = false\n')
    violations = RulerConfigValidRule().check(RepositoryContext(repo))
    assert len(violations) == 1
    assert violations[0].line is None
    assert "SECRET-VALUE" not in violations[0].message
    assert "nested" in violations[0].message and "default_agents" in violations[0].message


def test_ruler_copy_evidence_and_missing_or_changed_sources(tmp_path):
    repo, context = context_for("ruler", tmp_path)
    assert set(copies(context)) == {"AGENTS.md", "CLAUDE.md"}
    (repo / ".ruler/backend/api.md").unlink()
    assert copies(RepositoryContext(repo)) == {}


@pytest.mark.parametrize("suffix", ["\n", "\n\n", "\n<!-- Source: .ruler/AGENTS.md -->\n"])
def test_ruler_copy_rejects_unmatched_trailing_content(suffix, tmp_path):
    repo, _ = context_for("ruler", tmp_path)
    output = repo / "AGENTS.md"
    output.write_text(output.read_text() + suffix)
    assert "AGENTS.md" not in copies(RepositoryContext(repo))


@pytest.mark.parametrize(
    "name,filename", [("ruler", "AGENTS.md"), ("rulesync", ".cursor/rules/backend/api.mdc")]
)
def test_edited_output_is_not_a_copy(name, filename, tmp_path):
    repo, _ = context_for(name, tmp_path)
    path = repo / filename
    path.write_text(path.read_text() + "\nConsider using a separate connection pool.\n")
    assert filename not in copies(RepositoryContext(repo, rulesync_generated=True))


def test_rulesync_requires_explicit_ownership(tmp_path):
    repo, context = context_for("rulesync", tmp_path)
    assert copies(context) == {}
    assert set(copies(RepositoryContext(repo, rulesync_generated=True))) == {
        ".cursor/rules/backend/api.mdc",
        ".cursor/rules/release.mdc",
        ".claude/rules/backend/api.md",
        ".claude/rules/release.md",
    }


@pytest.mark.parametrize(
    "config",
    [
        {"targets": ["cursor"], "features": ["mcp"]},
        {"targets": ["cursor"], "global": True},
        {"targets": {"cursor": ["rules"]}},
        {"targets": ["cursor"], "outputRoots": ["packages/api"]},
        {"targets": ["cursor"], "inputRoots": [".rulesync"]},
        {"targets": ["claudecode"], "inputRoot": "."},
    ],
)
def test_rulesync_unsupported_configuration_keeps_all_checks(config, tmp_path):
    repo, _ = context_for("rulesync", tmp_path)
    (repo / "rulesync.jsonc").write_text(json.dumps(config))
    assert not copies(RepositoryContext(repo, rulesync_generated=True))


@pytest.mark.parametrize("name,source", [("ruler", ".ruler"), ("rulesync", ".rulesync/rules")])
def test_excluded_sources_never_suppress_outputs(name, source, tmp_path):
    repo, context = context_for(name, tmp_path, rulesync_generated=True)
    context.exclude_patterns.append(source + "/**")
    context.apply_excludes()
    assert not copies(context)


def test_symlinks_cannot_confer_generated_ownership_outside_repo(tmp_path):
    repo, _ = context_for("ruler", tmp_path)
    outside = tmp_path / "outside.md"
    outside.write_text("# Instructions\n\nConsider using a shared transaction.\n")
    (repo / ".ruler/escape.md").symlink_to(outside)
    (repo / "AGENTS.md").write_text(
        "<!-- Generated by Ruler -->\n\n\n<!-- Source: .ruler/escape.md -->\n\n"
        + outside.read_text()
    )
    context = RepositoryContext(repo)
    assert all(n.path.name != "escape.md" for n in context.lint_tree.find(RulerRuleBlock))
    assert "AGENTS.md" not in copies(context)


@pytest.mark.parametrize("value", [True, False, None])
def test_rulesync_option_roundtrip(value, tmp_path):
    path = tmp_path / ".skillsaw.yaml"
    path.write_text("version: '0.21.1'\nrulesync-generated: " + json.dumps(value))
    config = LinterConfig.from_file(path)
    assert config.rulesync_generated is (value or False)
    assert config.to_dict()["rulesync-generated"] is (value or False)


def test_rulesync_option_rejects_string(tmp_path):
    path = tmp_path / ".skillsaw.yaml"
    path.write_text("rulesync-generated: 'true'\n")
    with pytest.raises(ValueError, match="must be a boolean"):
        LinterConfig.from_file(path)
